// This file is automatically generated by the Supabase integration.
// The PCS telemetry wrapper below is intentionally kept here so every real
// browser request made through the single Supabase client can be correlated
// with a CST trace ID without exposing privileged credentials.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';
import { brokeredPreviewStorage } from './previewAuthStorage';

function isNewSupabaseApiKey(value: string): boolean {
  return value.startsWith('sb_publishable_') || value.startsWith('sb_secret_');
}

function randomHex(bytes: number): string {
  const out = new Uint8Array(bytes);
  if (typeof crypto !== 'undefined' && crypto.getRandomValues) crypto.getRandomValues(out);
  else for (let i = 0; i < bytes; i++) out[i] = Math.floor(Math.random() * 256);
  return Array.from(out, (b) => b.toString(16).padStart(2, '0')).join('');
}

function createTraceContext(): { traceId: string; traceparent: string } {
  const traceId = randomHex(16);
  const spanId = randomHex(8);
  return { traceId, traceparent: `00-${traceId}-${spanId}-01` };
}

function createSupabaseFetch(supabaseKey: string): typeof fetch {
  return async (input, init) => {
    const headers = new Headers(
      typeof Request !== 'undefined' && input instanceof Request ? input.headers : undefined,
    );
    if (init?.headers) new Headers(init.headers).forEach((value, key) => headers.set(key, value));
    if (isNewSupabaseApiKey(supabaseKey) && headers.get('Authorization') === `Bearer ${supabaseKey}`) {
      headers.delete('Authorization');
    }
    headers.set('apikey', supabaseKey);

    const requestUrl = typeof input === 'string' ? input : input.url;
    const isBrowser = typeof window !== 'undefined';
    const isTelemetryRequest = requestUrl.includes('/functions/v1/cst-telemetry');
    const trace = createTraceContext();
    headers.set('x-pcs-trace-id', trace.traceId);
    headers.set('traceparent', trace.traceparent);
    const started = typeof performance !== 'undefined' ? performance.now() : Date.now();

    try {
      const response = await fetch(input, { ...init, headers });
      if (isBrowser && !isTelemetryRequest) {
        const latency = Math.round((typeof performance !== 'undefined' ? performance.now() : Date.now()) - started);
        const token = headers.get('Authorization');
        const telemetryUrl = `${import.meta.env['VITE_SUPABASE_URL'] || ''}/functions/v1/cst-telemetry`;
        if (telemetryUrl.startsWith('http')) {
          void fetch(telemetryUrl, {
            method: 'POST',
            headers: {
              'content-type': 'application/json',
              ...(token ? { Authorization: token } : {}),
            },
            body: JSON.stringify({
              events: [{
                trace_id: trace.traceId,
                occurred_at: Date.now(),
                method: (init?.method || (input instanceof Request ? input.method : 'GET')).toUpperCase(),
                endpoint: requestUrl,
                status_code: response.status,
                latency_ms: latency,
              }],
            }),
            keepalive: true,
          }).catch(() => undefined);
        }
      }
      return response;
    } catch (error) {
      if (isBrowser && !isTelemetryRequest) {
        const latency = Math.round((typeof performance !== 'undefined' ? performance.now() : Date.now()) - started);
        const token = headers.get('Authorization');
        const telemetryUrl = `${import.meta.env['VITE_SUPABASE_URL'] || ''}/functions/v1/cst-telemetry`;
        if (telemetryUrl.startsWith('http')) {
          void fetch(telemetryUrl, {
            method: 'POST',
            headers: {
              'content-type': 'application/json',
              ...(token ? { Authorization: token } : {}),
            },
            body: JSON.stringify({
              events: [{
                trace_id: trace.traceId,
                occurred_at: Date.now(),
                method: (init?.method || (input instanceof Request ? input.method : 'GET')).toUpperCase(),
                endpoint: requestUrl,
                status_code: 0,
                latency_ms: latency,
                error_class: error instanceof Error ? error.name : 'NetworkError',
              }],
            }),
            keepalive: true,
          }).catch(() => undefined);
        }
      }
      throw error;
    }
  };
}

function createSupabaseClient() {
  const SUPABASE_URL = import.meta.env['VITE_SUPABASE_URL'] || process.env['SUPABASE_URL'];
  const SUPABASE_PUBLISHABLE_KEY = import.meta.env['VITE_SUPABASE_PUBLISHABLE_KEY'] || process.env['SUPABASE_PUBLISHABLE_KEY'];

  if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
    const missing = [
      ...(!SUPABASE_URL ? ['SUPABASE_URL'] : []),
      ...(!SUPABASE_PUBLISHABLE_KEY ? ['SUPABASE_PUBLISHABLE_KEY'] : []),
    ];
    const message = `Missing Supabase environment variable(s): ${missing.join(', ')}. Connect Supabase in Lovable Cloud.`;
    console.error(`[Supabase] ${message}`);
    throw new Error(message);
  }

  return createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
    global: { fetch: createSupabaseFetch(SUPABASE_PUBLISHABLE_KEY) },
    auth: {
      storage: brokeredPreviewStorage(),
      persistSession: true,
      autoRefreshToken: true,
    },
  });
}

let _supabase: ReturnType<typeof createSupabaseClient> | undefined;
export const supabase = new Proxy({} as ReturnType<typeof createSupabaseClient>, {
  get(_, prop, receiver) {
    if (!_supabase) _supabase = createSupabaseClient();
    return Reflect.get(_supabase, prop, receiver);
  },
});